public class MutableDateTime_add_TriageGen0Test {

    @Test(expected = IllegalArgumentException.class)
    public void testAdd_NullType_ThrowsException() {
        MutableDateTime dt = new MutableDateTime();
        dt.add(null, 1);
    }

    @Test
    public void testAdd_AmountIsOne_DoesNothing() {
        // The code says: if (amount != 1) { setMillis(...) }
        // Therefore, if amount == 1, the method should do nothing (no change in millis)
        long initialMillis = 1000000L;
        MutableDateTime dt = new MutableDateTime(initialMillis);

        dt.add(DurationFieldType.year(), 1);

        assertEquals("Millis should remain unchanged when amount is 1", initialMillis, dt.getMillis());
    }

    @Test
    public void testAdd_PositiveAmount_IncrementsField() {
        // Test adding years
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        long initialMillis = dt.getMillis();
        dt.add(DurationFieldType.year(), 2);

        // 2020 + 2 = 2022
        assertEquals(2022, dt.getYear());

        // Test adding months
        dt.add(DurationFieldType.monthOfYear(), 3);
        assertEquals(4, dt.getMonthOfYear());

        // Test adding days
        dt.add(DurationFieldType.dayOfMonth(), 10);
        assertEquals(11, dt.getDayOfMonth());
    }

    @Test
    public void testAdd_NegativeAmount_DecrementsField() {
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);

        // Subtract 1 year (amount != 1, so it enters the if block)
        dt.add(DurationFieldType.year(), -1);
        assertEquals(2019, dt.getYear());

        // Subtract 1 month
        dt.add(DurationFieldType.monthOfYear(), -1);
        assertEquals(12, dt.getMonthOfYear());
        assertEquals(2018, dt.getYear());
    }

    @Test
    public void testAdd_ZeroAmount_DoesNothing() {
        long initialMillis = 1609459200000L; // 2021-01-01
        MutableDateTime dt = new MutableDateTime(initialMillis);

        dt.add(DurationFieldType.dayOfMonth(), 0);

        assertEquals("Millis should remain unchanged when amount is 0", initialMillis, dt.getMillis());
    }

    @Test
    public void testAdd_LargeAmount_HandlesOverflow() {
        MutableDateTime dt = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0);
        dt.add(DurationFieldType.year(), 800);
        assertEquals(2800, dt.getYear());
    }
}
